// Audit11: a presentation queue consumes facts; it never calls act/settle or writes battle state.
export const COMBAT_VFX={feather:'assets/combat-vfx/black-feather.webp',break:'assets/combat-vfx/crystal-break.webp',cutin:'assets/combat-vfx/hadan-reference.webp',crest:'assets/runtime/crest-fallen.webp'};
export const COMBAT_TIMING={slash:{duration:320,hits:[120]},feather:{duration:520,hits:[290]},pierce:{duration:560,hits:[260]},volley:{duration:600,hits:[170,340]},power:{duration:540,hits:[220],breakAt:180},ultimate:{duration:1280,hits:[860],breakAt:820},guard:{duration:240,hits:[]}};
export function planCombatPresentation(events,action,{reduced=false}={}){
 const frames=[];let end=0,start=0,last=0,actor=null;const spec=COMBAT_TIMING[action]||COMBAT_TIMING.slash;
 for(const e of events){let at=last;
  if(e.kind==='playerAction'){start=end+(actor?60:0);actor='player';end=start+(reduced?(action==='volley'?300:180):spec.duration);at=start;}
  else if(e.kind==='enemyAction'){start=end+(actor?60:0);actor='enemy';end=start+(reduced?180:320);at=start;}
  else if(e.kind==='hit')at=start+(reduced?80+(e.hitIndex||0)*120:(spec.hits[e.hitIndex||0]??spec.hits[0]??120));
  else if(e.kind==='incomingHit'||e.kind==='enemyMiss'||e.kind==='enemyStopped')at=start+(reduced?80:140);
  else if(e.kind==='armorBreak')at=start+(reduced?50:spec.breakAt??180);
  else if(e.kind==='heal')at=actor==='enemy'?start+(reduced?120:240):last;
  else if(e.kind==='armorForm')at=start+(reduced?140:260);
  else if(e.kind==='phaseChange'){at=Math.max(last,end);end=at+(reduced?120:280);}
  else if(e.kind==='turnEnd'||e.kind==='deadline')at=Math.max(last,end);
  at=Math.max(last,at);last=at;frames.push({at,event:e});
 }
 return {frames,duration:Math.max(end,last)+ (reduced?120:320)};
}
export function preloadCombatVfx(){return Promise.all(Object.values(COMBAT_VFX).map(src=>new Promise(resolve=>{const img=new Image();const timer=setTimeout(resolve,500);img.onload=async()=>{try{await img.decode();}catch{}clearTimeout(timer);resolve();};img.onerror=()=>{clearTimeout(timer);resolve();};img.src=src;})));}
export function playCombatPresentation({arena,events,action,onFrame,onSound,reduced=false,signal}){
 const plan=planCombatPresentation(events,action,{reduced}),animations=new Set(),nodes=new Set(),timers=new Set();let closed=false,resolveDone;
 const done=new Promise(resolve=>{resolveDone=resolve;});
 const clean=()=>{if(closed)return;closed=true;for(const t of timers)clearTimeout(t);for(const a of animations)a.cancel();for(const n of nodes)n.remove();arena?.classList.remove('vfx-guarding','vfx-playing','vfx-ultimate-casting');signal?.removeEventListener('abort',clean);document.removeEventListener('visibilitychange',visibility);resolveDone();};
 const visibility=()=>{if(document.hidden)clean();};
 const animate=(node,keyframes,options)=>{if(!node?.animate)return;const a=node.animate(keyframes,options);animations.add(a);a.finished.catch(()=>{}).finally(()=>{animations.delete(a);node.remove();nodes.delete(node);});};
 const add=(cls,target=arena,text='')=>{if(!target)return null;const el=document.createElement('span');el.className='vfx '+cls;el.setAttribute('aria-hidden','true');el.textContent=text;target.append(el);nodes.add(el);return el;};
 const texture=(src,cls,target=arena)=>{const wrap=add(cls,target);if(!wrap)return null;const im=document.createElement('img');im.src=src;im.alt='';im.draggable=false;im.onerror=()=>{wrap.classList.add('vfx-fallback');im.remove();};wrap.append(im);return wrap;};
 const figure=side=>arena?.querySelector('.fighter-'+(side==='enemy'?'enemy':'player')+' .portrait-frame');
 const pulse=(side,big=false)=>{const target=figure(side);if(!target||reduced)return;const a=target.animate([{transform:'translateX(0)'},{transform:`translateX(${big?4:2}px)`,offset:.12},{transform:`translateX(${big?4:2}px)`,offset:.34},{transform:'translateX(0)'}],{duration:big?210:140});animations.add(a);a.finished.catch(()=>{}).finally(()=>animations.delete(a));};
 const number=(side,value,kind)=>{const el=add('vfx-number '+kind,figure(side),value);if(el)animate(el,[{opacity:0,transform:'translate(-50%,8px)'},{opacity:1,offset:.18,transform:'translate(-50%,-4px)'},{opacity:1,offset:.7},{opacity:0,transform:'translate(-50%,-27px)'}],{duration:reduced?180:300,fill:'both'});};
 const fire=()=>{if(reduced)return;const feather=texture(COMBAT_VFX.feather,'vfx-projectile');if(feather)animate(feather,[{opacity:0,transform:'translate(-65%,120%) rotate(-13deg) scale(.7)'},{opacity:1,offset:.25},{opacity:1,offset:.8},{opacity:0,transform:'translate(70%,-100%) rotate(-13deg) scale(1)'}],{duration:180,fill:'both'});};
 const later=(ms,fn)=>{const t=setTimeout(()=>{timers.delete(t);if(!closed){try{fn();}catch(error){console.error('Combat effect failed',error);clean();}}},ms);timers.add(t);};
