   if(action==='feather'&&!reduced&&arena?.clientHeight>=96){const el=texture(COMBAT_VFX.cutin,'vfx-cutin');if(el)animate(el,[{opacity:0,transform:'translateX(-10%)'},{opacity:1,offset:.14,transform:'translateX(0)'},{opacity:1,offset:.78},{opacity:0,transform:'translateX(4%)'}],{duration:270,fill:'both'});later(210,fire);}
   if(action==='pierce')later(reduced?0:150,fire);
   if(action==='volley'){later(reduced?0:70,fire);later(reduced?120:240,fire);}
   if(['power','ultimate'].includes(action)){const crest=texture(COMBAT_VFX.crest,'vfx-crest'+(action==='ultimate'?' vfx-ultimate':''));if(crest)animate(crest,[{opacity:0,transform:'scale(.8)'},{opacity:.8,offset:.4},{opacity:0,transform:'scale(1.15)'}],{duration:reduced?120:action==='ultimate'?820:220,fill:'both'});}
  }
  if(e.kind==='hit'){
   if(e.damage>0){number('enemy',Math.floor(e.damage).toLocaleString('ja-JP'),'vfx-out vfx-shot-'+(e.hitIndex||0));pulse('enemy',['pierce','ultimate'].includes(action));const slash=add('vfx-strike'+(action==='ultimate'?' vfx-finisher':''),figure('enemy'));arena?.classList.remove('vfx-ultimate-casting');if(slash)animate(slash,[{opacity:0,transform:'rotate(-25deg) scaleX(.1)'},{opacity:1,offset:.25},{opacity:0,transform:'rotate(-25deg) scaleX(1.2)'}],{duration:reduced?100:180});onSound?.(action==='ultimate'?'ultimate':'hit');}
   else number('enemy',e.landed===false?'MISS':'0','vfx-zero vfx-shot-'+(e.hitIndex||0));
  }
  if(e.kind==='incomingHit'){number('player',e.damage>0?'−'+Math.floor(e.damage).toLocaleString('ja-JP'):'0','vfx-in');if(e.damage>0){pulse('player');onSound?.(action==='guard'?'guard':'incoming');}}
  if(e.kind==='enemyMiss')number('player','回避','vfx-zero');
  if(e.kind==='enemyStopped')number('enemy','行動停止','vfx-zero');
  if(e.kind==='armorBreak'){const el=texture(COMBAT_VFX.break,'vfx-crystal',figure('enemy'));if(el)animate(el,[{opacity:1,transform:'scale(.88)'},{opacity:0,transform:'scale(1.12)'}],{duration:reduced?120:220,fill:'both'});number('enemy','殻解除','vfx-label');onSound?.('break');}
  if(e.kind==='armorForm')number('enemy','殻形成','vfx-label');
  if(e.kind==='phaseChange')number('enemy','第'+e.frame.phase+'形態','vfx-label');
  if(e.kind==='heal')number(e.target||'player','回復','vfx-heal');
  if(e.kind==='deadline')number('player','終末判定','vfx-in');
  onFrame?.(e.frame,e);
  if(!closed){if(index+1<plan.frames.length)playNext(index+1);else later(plan.duration-at,clean);}
 });};
 signal?.addEventListener('abort',clean,{once:true});document.addEventListener('visibilitychange',visibility);if(signal?.aborted||document.hidden||!plan.frames.length)clean();else playNext();
 return {done,cancel:clean,plan};
}

