@keyframes combat-number-rise{0%{opacity:0;transform:translate(-50%,12px) scale(.82)}20%{opacity:1;transform:translate(-50%,-8px) scale(1.14)}65%{opacity:1}100%{opacity:0;transform:translate(-50%,-45px) scale(1)}}
@keyframes foe-hit-recoil{0%,100%{transform:translate(0,0)}19%{transform:translate(8px,-3px);filter:brightness(1.55)}38%{transform:translate(-6px,2px)}61%{transform:translate(3px,-1px)}}
@keyframes player-hit-recoil{0%,100%{transform:translate(0,0)}19%{transform:translate(-8px,3px);filter:brightness(1.22)}38%{transform:translate(5px,-2px)}61%{transform:translate(-2px,1px)}}
@keyframes impact-glint{0%{opacity:0}20%{opacity:1}100%{opacity:0}}
