.summon-field{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none;color:var(--summon-color)}
.summon-crest{position:absolute!important;width:min(90vw,600px)!important;height:min(90vw,600px)!important;object-fit:contain!important;opacity:.22!important;animation:summon-emerge 1.3s ease-out both!important}
.summon-ring{position:absolute;width:min(78vw,540px);aspect-ratio:1;border:2px solid currentColor;border-radius:50%;box-shadow:0 0 30px currentColor,inset 0 0 20px currentColor;opacity:.5;animation:summon-orbit 1.6s ease-out both}
.summon-ring.outer{width:min(98vw,700px);border-style:dashed;animation-duration:2.3s;opacity:.3}
.summon-ray{position:absolute;width:2px;height:25vh;background:linear-gradient(transparent,currentColor,transparent);transform:rotate(var(--angle)) translateY(-32vh);animation:summon-ray 1.2s ease-out var(--delay) both}
#cinema.summon-cinema.rarity-R .outer{display:none}#cinema.summon-cinema.rarity-SR .summon-ring{border-radius:22%}#cinema.summon-cinema.rarity-SSR{background:radial-gradient(ellipse,#66522b,#211629 42%,#080a16 80%)}
@keyframes summon-tier{from{opacity:0;transform:scale(.55);filter:blur(8px)}to{opacity:1;transform:scale(1);filter:blur(0)}}
@keyframes summon-emerge{from{transform:scale(.7) rotate(-15deg)}to{transform:scale(1) rotate(0)}}
@keyframes summon-orbit{from{transform:scale(.5) rotate(-90deg)}to{transform:scale(1) rotate(30deg)}}
@keyframes summon-ray{from{opacity:0;translate:0 20px}to{opacity:.6;translate:0 0}}
@media(prefers-reduced-motion:reduce){#cinema.summon-cinema *,#cinema.summon-cinema .summon-crest{animation:none!important;filter:none!important}}

