/* audit11: local presentation layers never participate in the compact layout. */
.battle-stage .vfx{position:absolute;pointer-events:none;z-index:6;display:block}
.battle-stage .vfx img{display:block;width:100%;height:100%;object-fit:contain;pointer-events:none}
.vfx-cutin{inset:0;margin:auto;width:min(100%,calc(var(--combat-vh,100dvh) * .55));height:100%;max-height:100%;z-index:7!important;display:grid!important;place-items:center}
.vfx-cutin img{object-fit:contain!important}
.vfx-projectile{left:30%;top:30%;width:42%;height:40%;transform-origin:50% 50%}
.vfx-crest{inset:0;margin:auto;width:45%;height:85%;opacity:.7}
.vfx-ultimate{width:75%;height:100%}
.vfx-crystal{inset:6%;width:88%;height:88%}
.fighter .portrait-frame{isolation:isolate}
.fighter .info{z-index:12}
.vfx-number{left:50%;top:35%;font:bold clamp(17px,4.7vw,30px)/1.15 Georgia,serif;white-space:nowrap;text-shadow:0 1px 3px #000,0 0 8px #000;color:#fff0e5;z-index:15!important;font-variant-numeric:tabular-nums}
.vfx-shot-1{margin-left:8px;top:48%}.vfx-shot-0{margin-left:-4px}
.vfx-number.vfx-in{color:#ff9eac}.vfx-number.vfx-label{font:600 12px/1.3 -apple-system,sans-serif;color:#f4bbd7;top:15%}.vfx-number.vfx-zero{font:600 14px/1.3 -apple-system,sans-serif;color:#d4d2e4}.vfx-number.vfx-heal{font-size:13px;color:#a7edc9;top:62%}
.vfx-strike{left:12%;right:12%;top:45%;height:3px;background:#fff0e5;box-shadow:0 0 8px #c82a52;transform-origin:50% 50%}
.vfx-fallback{border-top:2px solid #f0d9e8;border-radius:50%}
.vfx-guarding .fighter-player .portrait-frame:after{content:'';position:absolute;inset:8%;border:2px solid #c6cfe4;border-radius:45% 45% 50% 50%;opacity:.65;pointer-events:none;z-index:5}
@media(prefers-reduced-motion:reduce){.vfx-strike{box-shadow:none}.vfx-cutin,.vfx-projectile{display:none!important}}
.vfx-playing .health span{transition:width .1s linear}
.vfx-ultimate-casting .fighter-player .portrait{filter:brightness(1.13);transition:filter .18s}
.vfx-finisher{height:5px;left:0;right:0}
@media(prefers-reduced-motion:reduce){.vfx-playing .health span{transition:none}.vfx-ultimate-casting .fighter-player .portrait{filter:none}}
.vfx-shield{inset:10%;border:2px solid #c6cfe4;border-radius:45% 45% 50% 50%;opacity:.65;box-shadow:inset 0 0 12px #b4c7eb22}
